import{_ as a,o as i,c as t,a2 as p}from"./chunks/framework.CHeM0PsO.js";const o=JSON.parse('{"title":"エクスポートとインポート","description":"","frontmatter":{},"headers":[],"relativePath":"ja/advanced/export-import.md","filePath":"ja/advanced/export-import.md","lastUpdated":1784904021000}'),e={name:"ja/advanced/export-import.md"};function n(h,s,l,k,d,r){return i(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="エクスポートとインポート" tabindex="-1">エクスポートとインポート <a class="header-anchor" href="#エクスポートとインポート" aria-label="Permalink to &quot;エクスポートとインポート&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><p>swag2mcp は ZIP アーカイブによる完全なワークスペースのラウンドトリップをサポートしています。ワークスペース全体（設定、spec ファイル、認証スクリプト）を ZIP ファイルにエクスポートし、別のマシンで復元できます。</p><h2 id="エクスポート" tabindex="-1">エクスポート <a class="header-anchor" href="#エクスポート" aria-label="Permalink to &quot;エクスポート&quot;">​</a></h2><p>ワークスペースのポータブルな ZIP バックアップを作成します。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># デフォルトファイルにエクスポート（swag2mcp-backup-&amp;lt;timestamp&amp;gt;.zip）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># カスタムパスでエクスポート</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/backups/swag2mcp-backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 特定の spec のみエクスポート</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo,store</span></span></code></pre></div><h3 id="エクスポートに含まれるもの" tabindex="-1">エクスポートに含まれるもの <a class="header-anchor" href="#エクスポートに含まれるもの" aria-label="Permalink to &quot;エクスポートに含まれるもの&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>説明</th></tr></thead><tbody><tr><td><code>swag2mcp.yaml</code></td><td>設定ファイル</td></tr><tr><td><code>specs/</code></td><td>すべての spec ファイル（OpenAPI/Swagger/Postman）</td></tr><tr><td><code>auth_scripts/</code></td><td>認証スクリプト</td></tr><tr><td><code>swag2mcp.meta</code></td><td>メタデータ（互換性のためのバージョン情報）</td></tr></tbody></table><p>キャッシュとレスポンスは<strong>エクスポートされません</strong> — これらは一時的なデータであり、復元時には古くなっています。</p><h3 id="デフォルトのファイル名" tabindex="-1">デフォルトのファイル名 <a class="header-anchor" href="#デフォルトのファイル名" aria-label="Permalink to &quot;デフォルトのファイル名&quot;">​</a></h3><p>出力パスを指定しない場合、ファイルはカレントディレクトリに <code>swag2mcp-backup-&lt;YYYY-MM-DD-HHMMSS&gt;.zip</code> として保存されます（UTC タイムスタンプ）。</p><h2 id="インポート" tabindex="-1">インポート <a class="header-anchor" href="#インポート" aria-label="Permalink to &quot;インポート&quot;">​</a></h2><p>ZIP バックアップからワークスペースを復元するか、spec ファイルをインポートします。</p><h3 id="zip-からの復元" tabindex="-1">ZIP からの復元 <a class="header-anchor" href="#zip-からの復元" aria-label="Permalink to &quot;ZIP からの復元&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ワークスペース全体を復元</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 上書きして復元</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/backup.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>ZIP は <code>swag2mcp export</code> で作成されたものである必要があります — 任意の ZIP ファイルは機能しません。</p><h3 id="単一の-spec-ファイルをインポート" tabindex="-1">単一の spec ファイルをインポート <a class="header-anchor" href="#単一の-spec-ファイルをインポート" aria-label="Permalink to &quot;単一の spec ファイルをインポート&quot;">​</a></h3><p>spec ファイルをダウンロードしてワークスペースに追加します：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/spec.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myspec</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/spec.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myspec</span></span></code></pre></div><h3 id="既存の設定からの一括インポート" tabindex="-1">既存の設定からの一括インポート <a class="header-anchor" href="#既存の設定からの一括インポート" aria-label="Permalink to &quot;既存の設定からの一括インポート&quot;">​</a></h3><p>指定された spec（ドメイン）のすべての collection spec ファイルをダウンロードします：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo,store</span></span></code></pre></div><p>各 collection の spec ファイルをダウンロードし、<code>specs/</code> に保存し、設定をローカルコピーを指すように更新します。</p><h2 id="ユースケース" tabindex="-1">ユースケース <a class="header-anchor" href="#ユースケース" aria-label="Permalink to &quot;ユースケース&quot;">​</a></h2><h3 id="バックアップ" tabindex="-1">バックアップ <a class="header-anchor" href="#バックアップ" aria-label="Permalink to &quot;バックアップ&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y-%m-%d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><h3 id="別のマシンへの転送" tabindex="-1">別のマシンへの転送 <a class="header-anchor" href="#別のマシンへの転送" aria-label="Permalink to &quot;別のマシンへの転送&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 古いマシンで</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ZIP を新しいマシンにコピーし、次を実行：</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp.zip</span></span></code></pre></div><h3 id="設定の共有" tabindex="-1">設定の共有 <a class="header-anchor" href="#設定の共有" aria-label="Permalink to &quot;設定の共有&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template.zip</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># template.zip を同僚と共有</span></span></code></pre></div><h2 id="エクスポート後の確認" tabindex="-1">エクスポート後の確認 <a class="header-anchor" href="#エクスポート後の確認" aria-label="Permalink to &quot;エクスポート後の確認&quot;">​</a></h2><p>ZIP ファイルが作成されたことを常に確認してください：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp-backup-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><h2 id="重要な注意点" tabindex="-1">重要な注意点 <a class="header-anchor" href="#重要な注意点" aria-label="Permalink to &quot;重要な注意点&quot;">​</a></h2><ul><li><strong>出力は <code>.zip</code> で終わるファイルパスである必要があります</strong> — ディレクトリを渡さないでください</li><li><strong>キャッシュとレスポンスは除外されます</strong> — 設定、spec、認証スクリプトのみが保存されます</li><li><strong>ZIP は自己完結型です</strong> — swag2mcp がインストールされた任意のマシンで復元できます</li><li><strong>Spec フィルター</strong> — <code>--spec</code> を使用して特定の spec のみをエクスポートまたはインポートします</li></ul>`,35)])])}const F=a(e,[["render",n]]);export{o as __pageData,F as default};
